// ─── Glossary ─────────────────────────────────────────────────────────────────

export const GLOSSARY = [
  // Tests
  { id: 'gre', term: 'GRE', category: 'Tests', full: 'Graduate Record Examination', definition: 'Standardized test required by most US graduate programs. Has three sections: Verbal Reasoning (130–170), Quantitative Reasoning (130–170), and Analytical Writing (0–6). Administered by ETS. Scores valid for 5 years. Many programs are now GRE-optional post-COVID, but top CS/engineering/science programs may still expect it.' },
  { id: 'gmat', term: 'GMAT', category: 'Tests', full: 'Graduate Management Admission Test', definition: 'Standardized test primarily for MBA programs. Sections: Quantitative, Verbal, Data Insights, and Analytical Writing. Score range 200–800. Competing with GRE for MBA admissions — many schools now accept either. The GMAT Focus Edition (launched 2023) is the current version.' },
  { id: 'toefl', term: 'TOEFL', category: 'Tests', full: 'Test of English as a Foreign Language', definition: 'English language proficiency test required for international students from non-English-speaking countries. TOEFL iBT (internet-based) is the standard format. Score range 0–120, with 4 sections of 30 points each: Reading, Listening, Speaking, Writing. Most programs require 80–100+. Scores valid for 2 years.' },
  { id: 'ielts', term: 'IELTS', category: 'Tests', full: 'International English Language Testing System', definition: 'Alternative English proficiency test to TOEFL. Score 0–9 (band score). The IELTS Academic version is for university admissions. Most US programs require a 6.5 or 7.0 band. Slightly more popular in the UK/Canada; both TOEFL and IELTS are widely accepted in the US.' },
  { id: 'gre-subject', term: 'GRE Subject', category: 'Tests', full: 'GRE Subject Test', definition: 'Specialized GRE tests for specific fields: Biology, Chemistry, Literature in English, Mathematics, Physics, Psychology. Required or recommended by some PhD programs — especially Physics and Math. Check each program. Separate registration from the GRE General Test.' },
  // Visa & Immigration
  { id: 'f1', term: 'F-1 Visa', category: 'Visa & Immigration', full: 'F-1 Student Visa', definition: 'The most common US visa for international students enrolled in accredited universities. Allows full-time study and limited work authorization (on-campus jobs, OPT, CPT). Your F-1 status is maintained through your I-20 — always keep your I-20 current. F-1 visa stamp allows entry; F-1 status (maintained by your DSO) governs what you can do.' },
  { id: 'j1', term: 'J-1 Visa', category: 'Visa & Immigration', full: 'J-1 Exchange Visitor Visa', definition: 'Visa for exchange visitors including researchers, professors, and some students in exchange programs. Has a Two-Year Home Residency Requirement (212(e)) for some categories — you must return to your home country for 2 years before getting certain US visas. Common for Fulbright scholars and some funded PhD positions.' },
  { id: 'i20', term: 'I-20', category: 'Visa & Immigration', full: 'Certificate of Eligibility for Nonimmigrant Student Status', definition: 'The most important document for F-1 students. Issued by your university\'s Designated School Official (DSO). You need it to apply for your F-1 visa, enter the US, and maintain legal status. It shows your program dates, funding, and authorization. Keep it current — your DSO must update it before it expires or if your status changes.' },
  { id: 'sevis', term: 'SEVIS', category: 'Visa & Immigration', full: 'Student and Exchange Visitor Information System', definition: 'The US government database that tracks all F-1 and J-1 students. Your school\'s DSO manages your SEVIS record. You must report to your ISSO within 30 days of arriving to activate your SEVIS record — failure to do so can result in loss of F-1 status. The SEVIS I-901 fee ($350 for F-1) must be paid before your visa interview.' },
  { id: 'ds160', term: 'DS-160', category: 'Visa & Immigration', full: 'Online Nonimmigrant Visa Application', definition: 'The online visa application form you fill out on the US State Department website before your visa interview. Takes 45–90 minutes. You\'ll upload a photo, answer questions about your background, and receive a confirmation barcode. Bring the printed DS-160 confirmation page to your visa interview — this is mandatory.' },
  { id: 'i94', term: 'I-94', category: 'Visa & Immigration', full: 'Arrival/Departure Record', definition: 'Electronic record created when you enter the US. It shows your admission class (F-1) and authorized period of stay (usually "D/S" — Duration of Status). Retrieve yours at cbp.dhs.gov/I94 after arrival. Required for SSN application, employment authorization, and tax purposes. Previously a paper card, now fully electronic.' },
  { id: 'opt', term: 'OPT', category: 'Visa & Immigration', full: 'Optional Practical Training', definition: 'Work authorization allowing F-1 students to work in their field of study for up to 12 months. Pre-completion OPT: before graduation. Post-completion OPT: after graduation. Apply through your DSO and USCIS — allow 90 days processing. The EAD card must arrive before you can start work. Apply at least 3 months before your graduation date.' },
  { id: 'stem-opt', term: 'STEM OPT', category: 'Visa & Immigration', full: 'STEM Optional Practical Training Extension', definition: 'A 24-month extension of OPT available to students who graduated from STEM-designated programs. Total with base OPT: 36 months of work authorization. Requires an approved I-983 Training Plan, must work for an E-Verify registered employer. Apply 90 days before your current OPT expires.' },
  { id: 'cpt', term: 'CPT', category: 'Visa & Immigration', full: 'Curricular Practical Training', definition: 'Work authorization for F-1 students to work during their studies as part of their curriculum. Must be integral to your degree — internships, co-ops, or required practicums. Approved by your DSO (no USCIS application needed). Full-time CPT for 12+ months eliminates your OPT eligibility — use part-time CPT whenever possible.' },
  { id: 'ead', term: 'EAD', category: 'Visa & Immigration', full: 'Employment Authorization Document', definition: 'The physical card that proves your authorization to work in the US. Required for post-completion OPT. Issued by USCIS after your OPT application is approved. Looks like a driver\'s license with your photo. Applied for at the same time as your OPT application (Form I-765). You cannot work without this card even if your OPT application is approved in the system.' },
  { id: 'h1b', term: 'H-1B', category: 'Visa & Immigration', full: 'H-1B Specialty Occupation Visa', definition: 'Work visa for specialty occupations requiring at least a bachelor\'s degree. The typical path after completing OPT. Your employer sponsors you. Annual cap of 85,000 visas with a lottery — extremely competitive. STEM OPT graduates have an extra lottery draw. Most F-1 students aim for H-1B after their 3 years of OPT ends.' },
  { id: 'dso', term: 'DSO / ISSO', category: 'Visa & Immigration', full: 'Designated School Official / International Students & Scholars Office', definition: 'Your university\'s authorized official(s) who manage F-1 student records in SEVIS and issue I-20s. The ISSO/OISS/DSO office is your primary resource for all immigration questions. Never make a significant change (dropping below full-time, transferring schools, taking a leave) without consulting your DSO first.' },
  // Finances & Tax
  { id: 'ssn', term: 'SSN', category: 'Finances & Tax', full: 'Social Security Number', definition: '9-digit number issued by the Social Security Administration. Required to work in the US, file taxes, open certain financial accounts, and build credit. International students can apply only after arriving in the US and having an employment authorization (usually an on-campus job offer). Apply at your local SSA office — takes 2–4 weeks to receive your card.' },
  { id: 'itin', term: 'ITIN', category: 'Finances & Tax', full: 'Individual Taxpayer Identification Number', definition: 'Tax identification number issued by the IRS for people who aren\'t eligible for an SSN. Some international students with no employment authorization use an ITIN for tax filing purposes. Format: 9XX-XX-XXXX. Apply using Form W-7 with your tax return. Not a work authorization — does not replace an SSN for employment.' },
  { id: '1040nr', term: '1040-NR', category: 'Finances & Tax', full: 'US Nonresident Alien Income Tax Return', definition: 'The tax return form F-1 students must file if they received US income (stipend, TA/RA pay, fellowship). F-1 students are generally considered nonresident aliens for tax purposes for the first 5 years. GLACIER Tax Prep or Sprintax are popular tools for nonresident alien tax filing. Due date: April 15 (or June 15 if no US income).' },
  { id: '8843', term: 'Form 8843', category: 'Finances & Tax', full: 'Statement for Exempt Individuals', definition: 'Tax form that F-1 students in their first 5 years in the US must file with the IRS every year — even if they had NO income. It exempts you from the "substantial presence test" that would make you a US tax resident. File it along with your 1040-NR, or on its own if you had no income. Deadline: April 15 (or June 15 if no income).' },
  // Academic
  { id: 'gpa', term: 'GPA', category: 'Academic', full: 'Grade Point Average', definition: 'US academic grading scale from 0.0 to 4.0 (or 4.3 at some schools for A+). For conversion: US grad programs typically want a 3.0+ (B average) minimum, with top programs expecting 3.5+. For Indian students, a 70–75% typically converts to ~3.3–3.5 GPA. WES or other evaluation services can provide an official conversion.' },
  { id: 'sop', term: 'SOP', category: 'Academic', full: 'Statement of Purpose', definition: 'A 500–1500 word essay required by most grad programs. It should explain: why you want this specific degree, what research/experience you\'ve done, why this specific program/school, and your career goals. It\'s often the most important part of a competitive application — it\'s what differentiates similar-GPA candidates.' },
  { id: 'lor', term: 'LOR', category: 'Academic', full: 'Letter of Recommendation', definition: 'Usually 2–3 letters from professors or employers who know your work well. Academic letters (from professors) are strongly preferred for research programs. Industry letters count more for professional masters and MBA. The letters should specifically address your academic ability, research potential, or professional performance — not just your character.' },
  { id: 'cv', term: 'CV', category: 'Academic', full: 'Curriculum Vitae', definition: 'An academic resume for graduate school and research applications. Unlike a resume (1 page), a CV can be 2–3+ pages and includes: education, research experience, publications, presentations, projects, awards, and skills. For industry-focused programs (MBA, MFE), a traditional 1-page resume is often preferred over a CV.' },
  { id: 'full-time', term: 'Full-Time Enrollment', category: 'Academic', full: 'Full-Time Enrollment Requirement', definition: 'F-1 students are required by law to maintain full-time enrollment every semester. For most US grad programs this means 9+ credit hours per semester. Dropping below full-time without DSO authorization can result in loss of F-1 status. Exceptions: final semester (with fewer credits to graduate), medical leave (requires DSO approval), reduced course load with DSO authorization.' },
  // Credentials
  { id: 'wes', term: 'WES', category: 'Credentials', full: 'World Education Services', definition: 'The most widely-used foreign credential evaluation service in the US. Verifies and converts international transcripts and degrees to their US equivalents. Required by many universities. A WES evaluation takes 7–12 weeks — start early. Document-by-document evaluation: verifies authenticity. Course-by-course: provides US GPA equivalent. The latter costs more but is required by more programs.' },
  { id: 'naces', term: 'NACES', category: 'Credentials', full: 'National Association of Credential Evaluation Services', definition: 'The accrediting body for credential evaluation services in the US. NACES members include WES, ECE, SpanTran, and others. Many US schools only accept evaluations from NACES members. Check your target school\'s requirements — some accept WES only, some accept any NACES member.' },
  { id: 'apostille', term: 'Apostille', category: 'Credentials', full: 'Apostille Certification', definition: 'An official certification that authenticates the origin of a public document for international use. Some countries require apostille-certified transcripts for credential evaluation. In India, the Ministry of External Affairs issues apostilles. Check if WES or your target school requires apostilled documents from your country.' },
  // Financial Aid
  { id: 'assistantship', term: 'Assistantship', category: 'Financial Aid', full: 'Graduate Assistantship (TA/RA)', definition: 'Part-time employment (typically 20 hours/week) at a university in exchange for a tuition waiver and a stipend. Teaching Assistantship (TA): assist professors with grading, labs, and sections. Research Assistantship (RA): work on a professor\'s research project. Both typically fully fund tuition and provide $18,000–$30,000/year stipend. More common in PhD programs; rare in coursework-only masters.' },
  { id: 'fellowship', term: 'Fellowship', category: 'Financial Aid', full: 'Graduate Fellowship', definition: 'Funded award given to students based on merit or research potential — no work required (unlike an assistantship). Often more prestigious than assistantships. NSF Fellowship, Fulbright, and university-specific fellowships. Typically covers tuition + stipend. Highly competitive. Having a fellowship is a strong differentiator for top PhD programs.' },
  { id: 'stipend', term: 'Stipend', category: 'Financial Aid', full: 'Graduate Stipend', definition: 'Regular cash payment to a graduate student, typically for TA or RA work. Unlike a salary, a stipend is not subject to the same employment tax rules (though it is still taxable income). Typical range: $1,500–$3,000/month depending on institution and field. PhD students in STEM typically receive higher stipends than humanities. Must file taxes on stipend income.' },
  { id: 'css-profile', term: 'CSS Profile', category: 'Financial Aid', full: 'College Scholarship Service Profile', definition: 'Financial aid application used by some private US universities for non-federal aid. Submitted through College Board. Less common for graduate students than undergrads, but some programs use it for fellowship consideration. Check your target school\'s financial aid requirements.' },
];

